357: {
358:     PlayerState state = {};
359:     if (!m_processHandle)
360:         return state;
361: 
362:     try
363:     {
364:         MemoryReader reader(m_processHandle);
365: 
366:         // Get D2R module base
367:         MODULEENTRY32 me32 = {sizeof(MODULEENTRY32)};
368:         HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, m_processId);
369:         if (hModuleSnap != INVALID_HANDLE_VALUE)
370:         {
371:             uintptr_t moduleBase = 0;
372: 
373:             if (Module32First(hModuleSnap, &me32))
374:             {
375:                 do
376:                 {
377:                     if (_wcsicmp(me32.szModule, L"D2R.exe") == 0)
378:                     {
379:                         moduleBase = (uintptr_t)me32.modBaseAddr;
380:                         break;
381:                     }
382:                 } while (Module32Next(hModuleSnap, &me32));
383:             }
384:             CloseHandle(hModuleSnap);
385: 
386:             if (moduleBase)
387:             {
388:                 // Pattern scan for player position (F3 0F 10 87 ?? ?? ?? ??)
389:                 // This finds: movss xmm0, [rdi + offset]
390:                 const unsigned char playerPosPattern[] = {
391:                     0xF3, 0x0F, 0x10, 0x87, 0x00, 0x00, 0x00, 0x00};
392:                 const char *mask = "xxxx????";
393: 
394:                 uintptr_t found = reader.FindPatternEx(
395:                     playerPosPattern,
396:                     mask,
397:                     moduleBase,
398:                     GameOffsets::PATTERN_SEARCH_SIZE);
399: 
400:                 if (found)
401:                 {
402:                     // Extract player state base from found pattern
403:                     // At found+4 we have the offset to player position within player structure
404:                     uintptr_t playerBase = found - GameOffsets::Player::POSITION_X;
405: 
406:                     // Read player position
407:                     state.position.x = reader.Read<float>(playerBase + GameOffsets::Player::POSITION_X);
408:                     state.position.y = reader.Read<float>(playerBase + GameOffsets::Player::POSITION_Y);
409:                     state.classType = reader.Read<int>(playerBase + GameOffsets::Player::CLASS_TYPE);
410:                     state.level = reader.Read<int>(playerBase + GameOffsets::Player::LEVEL);
411:                     state.experience = reader.Read<int>(playerBase + GameOffsets::Player::EXPERIENCE);
412: 
413:                     return state;
414:                 }
415:             }
416:         }
417:     }
418:     catch (...)
419:     {
420:         // Fallback to mock data on error
421:     }
422: 
423:     // Return mock data as fallback
