std::vector<MemoryHookTestResult> MemoryHookTest::RunAllTests(HANDLE processHandle, DWORD processId)
{
    std::vector<MemoryHookTestResult> results;

    results.push_back(TestPatternScanning(processHandle, processId));
    results.push_back(TestPlayerStateReading(processHandle, processId));
    results.push_back(TestMobListReading(processHandle, processId));
    results.push_back(TestMemoryReadAccuracy(processHandle, processId));

    return results;
}

MemoryHookTestResult MemoryHookTest::TestPatternScanning(HANDLE processHandle, DWORD processId)
{
    MemoryHookTestResult result;
    result.testName = "Pattern Scanning";
    result.success = false;

    try
    {
        MemoryReader reader(processHandle);

        // Get D2R module base
        MODULEENTRY32 me32 = {sizeof(MODULEENTRY32)};
        HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, processId);

        if (hModuleSnap == INVALID_HANDLE_VALUE)
        {
            result.message = "Failed to create module snapshot";
            return result;
        }

        uintptr_t moduleBase = 0;
        if (Module32First(hModuleSnap, &me32))
        {
            do
            {
                if (_wcsicmp(me32.szModule, L"D2R.exe") == 0)
                {
                    moduleBase = (uintptr_t)me32.modBaseAddr;
                    break;
                }
            } while (Module32Next(hModuleSnap, &me32));
        }
        CloseHandle(hModuleSnap);

        if (!moduleBase)
        {
            result.message = "D2R.exe module not found in target process";
            return result;
        }

        // Test player position pattern
        const unsigned char playerPosPattern[] = {
            0xF3, 0x0F, 0x10, 0x87, 0x00, 0x00, 0x00, 0x00};
        const char *playerMask = "xxxx????";

        uintptr_t playerPatternFound = reader.FindPatternEx(
            playerPosPattern,
            playerMask,
            moduleBase,
            GameOffsets::PATTERN_SEARCH_SIZE);

        // Test mob list pattern
        const unsigned char mobListPattern[] = {
            0x48, 0x8B, 0x41, 0x30};
        const char *mobMask = "xxxx";

        uintptr_t mobPatternFound = reader.FindPatternEx(
            mobListPattern,
            mobMask,
            moduleBase,
            GameOffsets::PATTERN_SEARCH_SIZE);

        std::stringstream ss;
        ss << "Player pattern: ";
        if (playerPatternFound)
        {
            ss << "FOUND at 0x" << std::hex << playerPatternFound << " | ";
        }
        else
        {
            ss << "NOT FOUND | ";
        }

        ss << "Mob pattern: ";
        if (mobPatternFound)
        {
            ss << "FOUND at 0x" << std::hex << mobPatternFound;
        }
        else
        {
            ss << "NOT FOUND";
        }

        result.message = ss.str();
        result.success = (playerPatternFound != 0) && (mobPatternFound != 0);
    }
    catch (const std::exception &e)
    {
        result.message = std::string("Exception: ") + e.what();
    }
    catch (...)
    {
        result.message = "Unknown exception during pattern scanning";
    }

    return result;
}

MemoryHookTestResult MemoryHookTest::TestPlayerStateReading(HANDLE processHandle, DWORD processId)
{
    MemoryHookTestResult result;
    result.testName = "Player State Reading";
    result.success = false;

    try
    {
        // Create a temporary BotEngine to use its GetPlayerState
        // We'll manually implement this to avoid circular dependency
