+Vector2D BotEngine::GameCoordToScreenCoord(const Vector2D& gameCoord) const
+{
+    // D2R uses isometric projection
+    // Screen X = (GameX - GameY) * cos(30°) + ScreenCenterX
+    // Screen Y = (GameX + GameY) * sin(30°) + ScreenCenterY
+    // For simplicity, approximate as 1:1 mapping with offset
+    Vector2D screenCoord;
+    screenCoord.x = gameCoord.x * 0.5f + gameCoord.y * 0.5f + 640.0f;
+    screenCoord.y = gameCoord.x * 0.25f - gameCoord.y * 0.25f + 360.0f;
+    return screenCoord;
+}
+
+Vector2D BotEngine::ScreenCoordToGameCoord(const Vector2D& screenCoord) const
+{
+    // Inverse of above transformation
+    Vector2D gameCoord;
+    float sx = screenCoord.x - 640.0f;
+    float sy = screenCoord.y - 360.0f;
+    gameCoord.x = sx + sy * 2.0f;
+    gameCoord.y = sx - sy * 2.0f;
+    return gameCoord;
+}
