// Execute waypoint clicks continuously
while (m_isRunning && currentRoute)
{
    for (int i = 0; i < routeLength && m_isRunning; i++)
    {
        // Convert hardcoded screen coordinates to game coordinates
        Vector2D screenTarget = {(float)currentRoute[i].x, (float)currentRoute[i].y};
        Vector2D gameTarget = ScreenCoordToGameCoord(screenTarget);

        // Get current player position
        PlayerState playerState = GetPlayerState();

        // Calculate click offset based on player's current position relative to target
        float dx = gameTarget.x - playerState.position.x;
        float dy = gameTarget.y - playerState.position.y;
        float distance = sqrt(dx * dx + dy * dy);

        // If player is very close to target, move to next waypoint
        if (distance < 50.0f)
        {
            // Check for nearby mobs and attack them
            std::vector<MobInfo> nearbyMobs = GetNearbyMobs(200.0f);
            if (!nearbyMobs.empty())
            {
                // Click on nearest mob
                float nearestDist = FLT_MAX;
                Vector2D nearestMobPos;
                for (const auto& mob : nearbyMobs)
                {
                    float mdx = mob.position.x - playerState.position.x;
                    float mdy = mob.position.y - playerState.position.y;
                    float mobDist = sqrt(mdx * mdx + mdy * mdy);
                    if (mobDist < nearestDist)
                    {
                        nearestDist = mobDist;
                        nearestMobPos = mob.position;
                    }
                }

                Vector2D mobScreenCoord = GameCoordToScreenCoord(nearestMobPos);
                int x = (int)mobScreenCoord.x;
                int y = (int)mobScreenCoord.y;

                // Add randomness
                x += (rand() % 15) - 7;
                y += (rand() % 15) - 7;

                // Send click
                SetCursorPos(x, y);
                Sleep(100);
                mouse_event(MOUSEEVENTF_LEFTDOWN, 0, 0, 0, 0);
                Sleep(50);
                mouse_event(MOUSEEVENTF_LEFTUP, 0, 0, 0, 0);
                Sleep(200);
                continue;
            }

            Sleep(300); // Brief pause before moving to next waypoint
            continue;
        }

        // Calculate screen position to click (move towards target)
        float moveScale = 100.0f / (distance + 0.01f); // Move ~100 units towards target
        float moveX = dx * moveScale;
        float moveY = dy * moveScale;

        Vector2D nextPos;
        nextPos.x = playerState.position.x + moveX;
        nextPos.y = playerState.position.y + moveY;

        Vector2D screenClick = GameCoordToScreenCoord(nextPos);
        int x = (int)screenClick.x;
        int y = (int)screenClick.y;

        // Add some randomness to avoid detection
        int randX = (rand() % 15) - 7; // ±7 pixels
        int randY = (rand() % 15) - 7;

        x += randX;
        y += randY;

        // Clamp to reasonable screen bounds (game area - wider range)
        if (x < 300)
            x = 300;
        if (x > 950)
            x = 950;
        if (y < 150)
            y = 150;
        if (y > 750)
            y = 750;

